import sys

def solve(string, reps, idx, pos):
	if idx < 0:
		return string[pos - 1]
	(l, ls) = reps[idx]
	if pos < ls:
		return solve(string, reps, idx - 1, pos)
	else:
		return solve(string, reps, idx - 1, l + (pos - ls))
